<?php
require_once 'config/database.php';require_once 'includes/functions.php';require_login();
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$conn->prepare('DELETE FROM categories WHERE id=?');$s->bind_param('i',$id);$s->execute();flash('Category deleted.');header('Location: categories.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name===''){flash('Category name is required.','danger');}else{try{if($id){$s=$conn->prepare('UPDATE categories SET name=?,description=? WHERE id=?');$s->bind_param('ssi',$name,$desc,$id);}else{$s=$conn->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->bind_param('ss',$name,$desc);}$s->execute();flash('Category saved successfully.');}catch(Throwable $e){flash('Could not save category. Check that its name is unique.','danger');}}header('Location: categories.php');exit;}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare('SELECT * FROM categories WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}$rows=$conn->query('SELECT c.*,COUNT(p.id) products_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name');$pageTitle='Categories';$active='categories';require 'includes/header.php';?>
<div class="row"><div class="col-md-4"><div class="card card-primary"><div class="card-header"><h3 class="card-title"><?=$edit?'Edit':'Add'?> Category</h3></div><form method="post"><div class="card-body"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-group"><label>Category Name *</label><input name="name" class="form-control" required value="<?=e($edit['name']??'')?>"></div><div class="form-group"><label>Description</label><textarea name="description" class="form-control"><?=e($edit['description']??'')?></textarea></div></div><div class="card-footer"><button class="btn btn-primary">Save Category</button> <a href="categories.php" class="btn btn-default">Clear</a></div></form></div></div><div class="col-md-8"><div class="card"><div class="card-header"><h3 class="card-title">Category List</h3><div class="card-tools"><input id="search" class="form-control form-control-sm" placeholder="Search categories"></div></div><div class="card-body table-responsive p-0"><table class="table table-hover" id="table"><thead><tr><th>ID</th><th>Name</th><th>Description</th><th>Products</th><th>Actions</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['id']?></td><td><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><?=$r['products_count']?></td><td><a class="btn btn-xs btn-info" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-xs btn-danger" onclick="return confirm('Delete this category?')" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></tbody></table></div></div></div></div><script>document.getElementById('search').addEventListener('input',function(){let q=this.value.toLowerCase();document.querySelectorAll('#table tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')})</script><?php require 'includes/footer.php';?>
